import sys, random
sys.path.insert(0,'/workspace/submission')
from treap import Priors, lean_insert, lean_extract_min, lean_extract_max, lean_delete, lean_recs
rng=random.Random(0); pr=Priors(); root=None; model=[]; ver=0; snaps={}
for i in range(4):
    r=rng.random(); print(i, 'r=',round(r,3), 'ver',ver, 'model',model)
    if r<0.25 and snaps:
        nm=rng.choice(list(snaps)); root, m, ver = snaps[nm]; model=list(m); print(' restore')
    elif r<0.35:
        ver+=1; snaps[len(snaps)]=(root,list(model),ver); print(' save')
    elif r<0.5 and model:
        root,node=lean_extract_min(root,ver); model.remove(node[0]); print(' extmin')
    elif r<0.6 and model:
        root,node=lean_extract_max(root,ver); model.remove(node[0]); print(' extmax')
    elif r<0.7 and model:
        key=rng.choice(model); root=lean_delete(root,key,ver); model.remove(key); print(' del')
    else:
        k=(rng.randint(0,9), i)
        if k in model: continue
        root=lean_insert(root,k,('r',k),pr.take(),ver); model.append(k); print(' ins',k)
    out=[]; lean_recs(root,out); print('  out', [x[0] for x in out], 'sorted', sorted(model))
PYEOF
